const items = $input.all();
const results = [];

// Fungsi menghitung SMA
function calculateSMA(data, period) {
  const sma = [];
  for (let i = 0; i < data.length; i++) {
    if (i < period - 1) { sma.push(null); continue; }
    let sum = 0;
    for (let j = 0; j < period; j++) { sum += data[i - j]; }
    sma.push(sum / period);
  }
  return sma;
}

// Fungsi menghitung RSI (14 periode)
function calculateRSI(data, period = 14) {
  let gains = 0, losses = 0;
  for (let i = 1; i <= period; i++) {
    const diff = data[i] - data[i - 1];
    if (diff >= 0) gains += diff; else losses -= diff;
  }
  let avgGain = gains / period;
  let avgLoss = losses / period;
  let rsi = [null];
  for (let i = 1; i < data.length; i++) {
    if (i <= period) { rsi.push(null); continue; }
    const diff = data[i] - data[i - 1];
    if (diff >= 0) { avgGain = (avgGain * (period - 1) + diff) / period; avgLoss = (avgLoss * (period - 1)) / period; }
    else { avgGain = (avgGain * (period - 1)) / period; avgLoss = (avgLoss * (period - 1) - diff) / period; }
    const rs = avgGain / avgLoss;
    rsi.push(100 - (100 / (1 + rs)));
  }
  return rsi;
}

for (const item of items) {
  const result = item.json.chart.result[0];
  const meta = result.meta;
  const closes = result.indicators.quote[0].close.filter(c => c !== null);

  const lastClose = closes[closes.length - 1];
  const ma50 = calculateSMA(closes, 50);
  const ma200 = calculateSMA(closes, 200);
  const rsiArr = calculateRSI(closes, 14);

  const lastMA50 = ma50[ma50.length - 1];
  const lastMA200 = ma200[ma200.length - 1];
  const lastRSI = rsiArr[rsiArr.length - 1];

  let signal = '⚪ Tidak ada sinyal saat ini';
  if (lastRSI !== null && lastRSI < 30) signal = '🔵 RSI Oversold (Potensi Buy)';
  else if (lastRSI !== null && lastRSI > 70) signal = '🔴 RSI Overbought (Potensi Sell)';
  else if (lastMA50 !== null && lastMA200 !== null && lastMA50 > lastMA200) signal = '🟢 Golden Cross (Buy Signal)';
  else if (lastMA50 !== null && lastMA200 !== null && lastMA50 < lastMA200) signal = '🔻 Death Cross (Sell Signal)';

  results.push({
    json: {
      symbol: meta.symbol,
      lastClose: lastClose,
      rsi: lastRSI !== null ? lastRSI.toFixed(2) : 'N/A',
      ma50: lastMA50 !== null ? lastMA50.toFixed(2) : 'N/A',
      ma200: lastMA200 !== null ? lastMA200.toFixed(2) : 'N/A',
      signal: signal
    }
  });
}
return results;

